using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json;
using ModelContextProtocol.Server;

namespace McpServer.Tools;

[McpServerToolType]
public sealed class ApiFetchTool
{
    [McpServerTool("fetch_api_data"),
     Description("Fetches data from an external API endpoint and returns the JSON response.")]
    public static async Task<string> FetchApiDataAsync(
        IHttpClientFactory httpClientFactory,
        [Description("The relative path to append to the base API URL (e.g. \"users/42\")")]
        string path,
        CancellationToken cancellationToken)
    {
        using var client = httpClientFactory.CreateClient("ExternalApi");

        using var response = await client.GetAsync(path, cancellationToken);
        response.EnsureSuccessStatusCode();

        var json = await response.Content.ReadFromJsonAsync<JsonElement>(cancellationToken);
        return JsonSerializer.Serialize(json, new JsonSerializerOptions { WriteIndented = true });
    }
}

using System.ComponentModel;
using ModelContextProtocol.Server;

namespace McpServer.Prompts;

[McpServerPromptType]
public sealed class SummarizationPrompt
{
    [McpServerPrompt("summarize"),
     Description("Creates a prompt that asks the model to summarize the provided text.")]
    public static IList<Microsoft.Extensions.AI.ChatMessage> Summarize(
        [Description("The text to summarize")] string text,
        [Description("Optional maximum number of sentences for the summary")]
        string? maxSentences = null)
    {
        var constraint = maxSentences is not null
            ? $" Use no more than {maxSentences} sentences."
            : string.Empty;

        return
        [
            new(Microsoft.Extensions.AI.ChatRole.User,
                $"Please provide a concise summary of the following text.{constraint}\n\n{text}")
        ];
    }
}

